insert into public.processes(codigo_proceso,area_id,tipo_proceso_id,nombre_proceso,responsable_principal,responsable_secundario,fecha_inicio,fecha_fin_programada,fecha_fin_real,estado_id,prioridad_id,porcentaje_avance,dependencia_externa,documento_respaldo,proxima_accion,objetivo,observaciones,fecha_proxima_revision,requiere_accion_gerencial,confidencialidad,activo,created_at,updated_at) values ('TRV-2026-0025',(select id from public.areas where nombre='DISEÑO DE LA OBRA PÚBLICA' limit 1),(select id from public.process_types where nombre='DISEÑO' limit 1),'CEMENTERIO DE LICAN','Ing. Marcela Pazmiño',null,'2026-03-23','2026-04-01','2026-04-01',(select id from public.process_statuses where nombre='Finalizado' limit 1),(select id from public.priorities where nombre='Baja' limit 1),100,'DISEÑO DE LA OBRA PÚBLICA','1139896','Remitir la información Técnica Correspondiente para continuar con el proceso Contractual con la Dirección de Gestión de la Obra Pública','ENTREGA DEL PROYECTO "READECUACIÓN DEL CEMENTERIO DE LA CABECERA PARROQUIAL DE LICAN"','Observación: 01ABR2026 Se entrega con Memo Nro. GADMR-J-DOP-2026-0016-M',null,false,'Interna',true,'2026-07-08T00:00:00Z','2026-07-08T00:00:00Z') on conflict (codigo_proceso) do update set area_id=excluded.area_id, tipo_proceso_id=excluded.tipo_proceso_id, nombre_proceso=excluded.nombre_proceso, responsable_principal=excluded.responsable_principal, responsable_secundario=excluded.responsable_secundario, fecha_inicio=excluded.fecha_inicio, fecha_fin_programada=excluded.fecha_fin_programada, fecha_fin_real=excluded.fecha_fin_real, estado_id=excluded.estado_id, prioridad_id=excluded.prioridad_id, porcentaje_avance=excluded.porcentaje_avance, dependencia_externa=excluded.dependencia_externa, documento_respaldo=excluded.documento_respaldo, proxima_accion=excluded.proxima_accion, objetivo=excluded.objetivo, observaciones=excluded.observaciones, fecha_proxima_revision=excluded.fecha_proxima_revision, requiere_accion_gerencial=excluded.requiere_accion_gerencial, confidencialidad=excluded.confidencialidad, activo=excluded.activo, updated_at=excluded.updated_at;
